-- KB-029 distinct human/workload identity, delegation, approval attribution and accountable emergency-access evidence.
-- Additive candidate semantic correction. No changes to historical customer assessments, security findings, existing evidence or deployment decisions.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"Multiple humans, workloads or agents share or reuse privileged identities, credentials or approvals so consequential actions cannot be reliably attributed to the accountable actor.","customer_symptom":"Audit records show a generic, shared or reused principal for privileged agent, tool, approval or evidence-signing actions, preventing independent attribution to the human, workload owner or delegated subject responsible for the action.","credible_failure_or_attack":"A shared privileged account, reusable service credential, ambiguous delegated identity, self-approval path or unattributed break-glass mechanism allows different actors to perform consequential operations while audit records collapse them into one apparently valid identity.","affected_assets":["privileged human accounts and authenticated sessions","workload, service and agent identities","delegated user context and impersonation chains","approval and separation-of-duties records","tool calls and downstream consequential actions","security evidence, signatures and audit trails"],"default_severity":"high","severity_rationale":"Default high rating reflects the loss of accountability and potential privilege abuse before customer-specific exposure, action impact, compensating controls and exception governance are verified.","applicability":["organisations requiring accountable decisions"],"threat_actor_or_failure_source":"shared privileged user, generic account, reused service credential, ambiguous workload identity, unauthorized delegation, approval conflict or unattributed emergency access","trust_boundary":"Between authenticated human/workload identity and each consequential approval, delegated agent/tool action, downstream effect and audit record that must preserve independent actor provenance.","operational_impact":"Unattributable privileged actions weaken prevention, investigation, non-repudiation and accountable human review. Containment may require disabling shared credentials, isolating affected workflows and re-establishing independently attributable identity and approval evidence."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-11","next_review_due":"2026-12-10","change_triggers":["ARL-KB-029 identity, privileged-account, workload-identity or approval-attribution change","ARL-KB-029 introduction of shared, generic, break-glass or service credentials","ARL-KB-029 unattributable privileged action or shared-account incident","ARL-KB-029 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='1e4c103f9e99834f7e74fa2ef404543d37af3fcc9845866ed12f7a4f57ac6b79', updated_at='2026-10-11' WHERE id='ARL-KB-029';
UPDATE risk_knowledge_checks SET objective='Determine whether every consequential human, workload, delegated agent/tool, approval and evidence-signing action is bound to a distinct verified principal or an explicitly governed, individually attributable emergency exception.', method='Bind the exact assessed build, environment and identity scope. Inspect organisation-approved principal, workload, delegation, separation-of-duties and break-glass policy plus identity-provider, session, approval, tool and audit configuration. With separate written owner authorization and synthetic staging principals, exercise bounded positive distinct-human/workload paths and negative generic/shared identity, missing-principal, swapped-delegation, self-approval, reused-approval and unattributed emergency-access cases. Correlate authenticated actor, delegated subject, approval, tool call, downstream effect and tamper-evident audit record. ARL never infers a unique human from a service principal, display name, IP address or model assertion.', required_evidence_json='["ARL-KB-029 assessed system, exact version, environment and consequential human, workload, agent/tool, delegated identity, approval and audit scope","ARL-KB-029 organisation-approved unique-principal, workload ownership, delegation, separation-of-duties and break-glass accountability policy with version, effective dates and accountable owner","ARL-KB-029 source or configuration evidence for identity/session binding, shared credential prevention, workload issuer and audience, delegated actor provenance, named approval attribution, audit integrity and fail-closed ambiguous-principal handling","ARL-KB-029 bounded positive evidence of distinct synthetic human and workload principals across approved authentication, delegation, approval, tool and downstream actions","ARL-KB-029 bounded negative evidence of prohibited generic or shared privileged identity, missing principal, swapped delegation, conflicting self-approval, reused approval token and unattributed emergency access denied or quarantined before material effects","ARL-KB-029 observed runtime correlation across authenticated actor, workload identity, delegated subject, approval, policy decision, tool execution, downstream effect and tamper-evident audit evidence","ARL-KB-029 reviewer identity, role, written testing authorization, policy and exception review, timestamp, assessed version, evidence digest, untested paths, limitations and accountable decision"]', pass_condition='KB-029 passes only after accountable human review of the exact assessed version shows distinct attributable human and workload identities on applicable consequential paths, verified delegation and approval provenance, governed emergency exceptions, bounded positive and negative synthetic evidence, denial or quarantine of prohibited ambiguous/shared authority before material effects, and independently reviewable runtime audit linkage.', fail_condition='KB-029 is a confirmed FAIL only where reproducible exact-version evidence demonstrates accepted prohibited shared or generic privileged authority, consequential action without required independent actor provenance, unauthorized delegation or approval, or an emergency-access path that violates the approved attribution policy. Missing identity inventory, policy, active-test authorization, runtime correlation, exception evidence or reviewer decision requires INCONCLUSIVE / EVIDENCE GAP / REVIEW REQUIRED: block PASS and deployment without inventing a confirmed vulnerability.', limitations='This bounded test does not prove that untested accounts, external identity providers, endpoints or future versions are free from shared-identity or attribution failures. Service principals may legitimately represent workloads only where ownership, purpose, delegation and accountable review are independently established.', content_digest='0fb028acd8e4bad90ab14f8d23a1242023c2ba1dc73953d7ca2e15c2f9546927', updated_at='2026-10-11' WHERE entry_id='ARL-KB-029';
UPDATE risk_knowledge_solutions SET control_objective='Provide independently attributable human and workload identities and preserve actor, delegation, approval and downstream provenance for every consequential action, with tightly governed emergency exceptions.', recommended_remediation='Eliminate shared privileged credentials; issue distinct human and workload identities, preserve original delegated user context, separate requester and approver where required, bind approvals and tool actions to verified principals, and make break-glass access individually attributable, time-bounded and retrospectively reviewed.', implementation_principles_json='["ARL-KB-029: Issue distinct human identities and purpose-bound workload identities with named accountable owners; never treat a generic service principal as proof of a unique human.","ARL-KB-029: Preserve authenticated actor, delegated subject, workload/tool caller, approval identity, policy version and downstream effect as separate correlated audit fields.","ARL-KB-029: Enforce separation of duties and prevent approval reuse or self-approval where the approved policy requires independent authorization.","ARL-KB-029: Permit emergency access only through individually attributable, time-bounded, specially logged mechanisms with accountable retrospective review."]', monitoring='Monitor generic/shared privileged identities, concurrent or cross-user credential reuse, principal changes within delegation chains, approval reuse, self-approval conflicts, unattributed break-glass use, missing actor fields and mismatches between identity-provider, tool and downstream audit events.', containment='Disable or rotate suspected shared privileged credentials, suspend ambiguous delegated authority, isolate affected approval/tool routes, preserve identity-provider and downstream audit evidence, and require accountable review before re-enablement.', retest_acceptance_json='["ARL-KB-029: Exact remediated build, approved accountability policy, principal inventory, workload owners, delegation rules and permitted emergency exceptions are recorded.","ARL-KB-029: Distinct synthetic human and workload positive paths complete within approved scope with independently correlated actor, delegation, approval, tool and downstream evidence.","ARL-KB-029: Generic/shared privileged identity, missing-principal, swapped-delegation, self-approval, reused-approval and unattributed emergency-access variants are denied or quarantined before material effects with trustworthy audit evidence.","ARL-KB-029: Reviewer records written authorization, tester/reviewer roles, timestamps, evidence digests, exception handling, untested paths, residual limitations and final accountable decision."]', content_digest='d26680117b17de919ee6be0f905a499929163abf9df603513b5cd0cdf7b2440d', updated_at='2026-10-11' WHERE entry_id='ARL-KB-029';
UPDATE risk_knowledge_entry_classification SET review_date='2026-10-11', updated_at='2026-10-11' WHERE entry_id='ARL-KB-029';
